create table eba_demo_ig_people (
    id       number,
    rating   number,
    name     varchar2(255 byte),
    country  varchar2(50 byte),
    from_yr  number,
    to_yr    number,
    link     varchar2(255 byte),
    category varchar2(10 byte),
    gender   varchar2(1 byte),
    flex1    varchar2(1000 byte),
    flex2    varchar2(1000 byte),
    flex3    varchar2(1000 byte)
);

alter table eba_demo_ig_people
    add constraint eba_demo_ig_people_pk primary key ( id )
        using index enable;


